declare const customerIdBrand: unique symbol;
export type CustomerId = string & { readonly [customerIdBrand]: true };

export class Customer {
  constructor(readonly id: CustomerId, public name: string) {}
  rename(name: string): void { this.name = name; }        // state may change
  sameAs(other: Customer): boolean { return other.id === this.id; }
}
